  /**
   * Prompt tokens written to the provider's cache. Zero for providers that do not report it.
   * @minimum 0
   */
  cacheWriteTokens: number;
  /**
   * Output tokens, including reasoning.
   * @minimum 0
   */
  outputTokens: number;
  /**
   * Output tokens spent on reasoning.
   * @minimum 0
   */
  reasoningTokens: number;
  /** @minimum 0 */
